import numpy as np
def fig_continentes():
    fig, ax = plt.subplots(figsize=(6.2, 2.6)); c = ["Asia","América","África","Antártida","Europa","Oceanía"]; v = [44.6, 42.5, 30.4, 14.2, 10.2, 8.5]
    ax.barh(c[::-1], v[::-1], color=O); ax.set_xlabel("millones de km²", fontsize=8); ax.tick_params(labelsize=8)
    for i, x in enumerate(v[::-1]): ax.text(x + .5, i, str(x).replace(".", ","), va="center", fontsize=7.5)
    ax.spines[["top","right"]].set_visible(False); return png(fig)
def fig_mar():
    fig, ax = plt.subplots(figsize=(6.4, 2.4)); ax.axis("off"); ax.set_xlim(-60, 380); ax.set_ylim(0, 3)
    ax.add_patch(plt.Rectangle((-60, 0), 60, 3, fc="#c9b18a")); ax.text(-30, 1.5, "Costa", ha="center", va="center", fontsize=8)
    for x0, x1, col, t in ((0, 12, "#2f6fa8", "Mar territorial\n12 millas"), (12, 200, "#6fa3cf", "Zona económica exclusiva\nhasta 200 millas"), (200, 350, "#bcd7ec", "Plataforma continental\nhasta 350 millas")):
        ax.add_patch(plt.Rectangle((x0, 0), x1 - x0, 3, fc=col)); ax.text((x0 + x1) / 2 if x1 > 20 else 6, 1.5 if x1 > 20 else 3.25, t, ha="center", va="center", fontsize=7.5, color="#10233a")
    return png(fig)
